const input = $input.first().json || {};
const requestId = input.request_id || '';
const toolInput = input.tool_input || {};
const pdfUrl = toolInput.pdf_url || toolInput.pdfUrl || '';
const base64Pdf = toolInput.base64_pdf || toolInput.base64Pdf || '';
if (!pdfUrl && !base64Pdf) {
  return [{ json: { request_id: requestId, success: false, data: {}, error: { message: 'tool_input.pdf_url veya tool_input.base64_pdf zorunlu', code: 'PDF_INPUT_REQUIRED', node: 'Validate PDF Input' }, usage: { time_ms: 0, tokens: null, cost: null }, artifacts: [] } }];
}
return [{ json: { ...input, request_id: requestId, _pdf_url: pdfUrl, _has_base64: !!base64Pdf } }];

const input = $input.first().json;
const source = input._pdf_url ? `pdf_url: ${input._pdf_url}` : 'base64_pdf';
const summary = `PDF özeti (MVP): Kaynak ${source}. Bu wrapper şablonu production'da gerçek PDF parse + LLM özet node'ları ile genişletilmelidir.`;
const artifactUrl = input._pdf_url || null;
return [{ json: { request_id: input.request_id, success: true, data: { summary }, error: null, usage: { time_ms: 120, tokens: null, cost: null }, artifacts: artifactUrl ? [{ type: 'link', name: 'source_pdf', url: artifactUrl, meta: { source: 'pdf_url' } }] : [] } }];
